import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { LmlError } from "../../src/contracts.js";
import { loadDocument } from "../../src/lml/index.js";

// Golden cases generated by the Ruby reference (lutaml-model #1116 @ d05b3af, card 02g):
// `bundle exec ruby -Ilib test/lml/fixtures/any_attribute.generator.rb <out.json>` in that worktree.
interface Golden {
  readonly name: string;
  readonly input: string;
  readonly expect: { readonly reason: string; readonly location: string | null; readonly detail: string } | null;
}
const cases = JSON.parse(readFileSync(new URL("./fixtures/any_attribute.json", import.meta.url), "utf8")) as Golden[];
const enc = new TextEncoder();

function run(c: Golden): LmlError | undefined {
  try {
    loadDocument(enc.encode(c.input), "json");
  } catch (error) {
    if (error instanceof LmlError) return error;
    throw error;
  }
  return undefined;
}

describe("any_attribute rule parity with the Ruby validator (golden cases)", () => {
  it("has accepted and refused cases", () => {
    expect(cases.filter((c) => c.expect === null).length).toBeGreaterThanOrEqual(8);
    expect(cases.filter((c) => c.expect !== null).length).toBeGreaterThanOrEqual(25);
  });

  it.each(cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const error = run(c);
    if (c.expect === null) {
      expect(error?.info, "accepted by Ruby, so by TS").toBeUndefined();
      return;
    }
    expect(error, "refused by Ruby, so by TS").toBeDefined();
    expect(error?.info.reason).toBe(c.expect.reason);
    expect(error?.info.location).toBe(c.expect.location ?? "");
  });

  it("measured: Ruby's validator does not check the rule's position (the exporter emits it last)", () => {
    const byName = new Map(cases.map((c) => [c.name, c]));
    expect(byName.get("valid_not_last")?.expect).toBeNull();
    expect(run(byName.get("valid_not_last") as Golden)).toBeUndefined();
  });
});
